102	  return new Promise((resolve, reject) => {
103	    const timer = setTimeout(() => reject(new Error("command timed out")), timeoutMs);
104	    conn.exec(command, (err, stream) => {
105	      if (err) { clearTimeout(timer); return reject(err); }
106	      let out = "";
107	      stream
108	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, out }); })
109	        .on("data", (d: Buffer) => { out += d.toString(); })
110	        .stderr.on("data", (d: Buffer) => { out += d.toString(); });
111	    });
