/**
 * Shared-hosting primitives (Phase 1 foundation).
 *
 * Pure, framework-free helpers the account lifecycle is built on — unit-tested so
 * the parts that end up in a shell command on a MULTI-TENANT box (a username, a
 * quota, a domain in an nginx `server_name`) are provably well-formed before they
 * ever get there. On a shared box a single bad interpolation is not one
 * customer's bug, it is everyone's; these validators are the first line of that.
 */

/** A syntactically valid domain for a name-based vhost (no scheme, no path). */
const DOMAIN_RE = /^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;

/** True for a hostname safe to place in an nginx `server_name` / a cert request. */
export function isValidHostingDomain(domain: string): boolean {
  const d = String(domain ?? "").trim().toLowerCase().replace(/\.$/, "");
  return DOMAIN_RE.test(d);
}

export function normalizeHostingDomain(domain: string): string {
  return String(domain ?? "").trim().toLowerCase().replace(/^www\./, "").replace(/\.$/, "");
}

/**
 * A safe jailed Linux username for an account, derived deterministically and kept
 * short (Linux caps usernames at 32 chars; some tooling chokes past 16). Starts
 * with a letter, lowercase alnum only — nothing a shell could ever interpret.
 *
 * `seed` (email localpart or account id) proposes a readable base; `disambiguator`
 * (a slice of the account id) guarantees per-node uniqueness without a DB probe.
 * The result still has to pass `isValidUnixUsername` before use, and the caller
 * resolves any residual collision against the DB (`@@unique([hostingNodeId, username])`).
 */
export function deriveUsername(seed: string, disambiguator: string): string {
  const base = String(seed ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "")
    .replace(/^[0-9]+/, "") // must not start with a digit
    .slice(0, 8);
  const suffix = String(disambiguator ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "")
    .slice(0, 6);
  // Guarantee a non-empty body so the result always clears the min-length rule
  // even when both inputs sanitise away to nothing.
  const body = `${base}${suffix}` || "acct";
  return `nx${body}`.slice(0, 16);
}

const UNIX_USER_RE = /^[a-z][a-z0-9]{2,31}$/;

/** True only for a shell-inert, policy-valid Linux username. */
export function isValidUnixUsername(name: string): boolean {
  return UNIX_USER_RE.test(String(name ?? ""));
}

export type HostingPlanLimits = {
  diskGB: number;
  maxSites: number;
  maxDatabases: number;
  bandwidthTB: number;
  phpVersions: string[];
};

/** The effective, sanitised limits for an account, snapshotted from its plan. */
export function planLimits(plan: {
  diskGB: number;
  maxSites: number;
  maxDatabases: number;
  bandwidthTB: number;
  phpVersions: string;
}): HostingPlanLimits {
  const php = String(plan.phpVersions ?? "")
    .split(",")
    .map((v) => v.trim())
    .filter((v) => /^\d\.\d$/.test(v));
  return {
    diskGB: Math.max(1, Math.floor(plan.diskGB || 1)),
    maxSites: Math.max(1, Math.floor(plan.maxSites || 1)),
    maxDatabases: Math.max(0, Math.floor(plan.maxDatabases || 0)),
    bandwidthTB: Math.max(0, plan.bandwidthTB || 0),
    phpVersions: php.length ? php : ["8.3"],
  };
}

/** Disk quota in KB blocks for `setquota` (1 GB = 1,048,576 one-KB blocks). */
export function diskQuotaBlocks(diskGB: number): number {
  return Math.max(1, Math.floor(diskGB)) * 1024 * 1024;
}

/**
 * Inode (file-count) quota for `setquota`, the containment for a DoS the block
 * quota alone doesn't stop: a tenant creating MILLIONS of tiny files exhausts the
 * shared filesystem's inode table — filling no disk blocks but breaking every
 * neighbour's ability to create a file. `setquota … <isoft> <ihard>` of `0 0`
 * means UNLIMITED inodes, so a real cap is required here. Scales gently off the
 * plan's disk size but is floored (a 1 GB plan still gets working room) and
 * ceilinged (a huge plan can't effectively uncap); hard carries 25% headroom
 * over soft so a tenant hits the soft warning before the hard wall.
 */
export function diskQuotaInodes(diskGB: number): { soft: number; hard: number } {
  const gb = Math.max(1, Math.floor(diskGB || 1));
  const soft = Math.min(2_000_000, Math.max(200_000, gb * 50_000));
  const hard = Math.floor(soft * 1.25);
  return { soft, hard };
}

/**
 * What the customer sets in DNS to point a domain at their account: an A record
 * to the node's shared public IP. (A CNAME to the node FQDN is offered too when
 * the node has one, for sub-domains / apex-ALIAS providers.)
 */
export function pointToRecords(node: { publicIp: string; hostnameFqdn?: string | null }): {
  aRecord: string;
  cnameTarget: string | null;
} {
  return { aRecord: node.publicIp, cnameTarget: node.hostnameFqdn?.trim() || null };
}

/** The absolute home + web root for an account's jailed user. */
export function accountPaths(username: string): { home: string; webroot: string; fpmPool: string } {
  return {
    home: `/home/${username}`,
    webroot: `/home/${username}/public_html`,
    fpmPool: `/etc/php/fpm-pools/${username}.conf`,
  };
}

/**
 * Per-account directory holding the self-signed FALLBACK cert generated at
 * provision time (fullchain.pem + privkey.pem). Its whole purpose: nginx can
 * `listen 443 ssl` from the moment the account exists, so HTTPS shows a cert
 * WARNING, never ERR_CONNECTION_REFUSED — the real Let's Encrypt cert replaces it
 * once the SSL sweep issues one. Username is already validated before this reaches
 * a shell (isValidUnixUsername), same as accountPaths. */
export function selfSignedCertDir(username: string): string {
  return `/etc/ssl/hosting/${username}`;
}

/**
 * A single DNS label for a subdomain (the part left of the primary domain, e.g.
 * "shop" in shop.example.com). No dots — a subdomain is exactly one label deep;
 * lowercase alnum + internal hyphens only, so it is shell-inert AND a valid
 * hostname label + directory name.
 */
const SUB_LABEL_RE = /^[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])?$/;
export function isValidSubdomainLabel(label: string): boolean {
  return SUB_LABEL_RE.test(String(label ?? "").trim().toLowerCase());
}

/**
 * A hard-to-guess token for the Adminer DB-manager directory dropped inside an
 * account's webroot (`/nxtools-<token>/adminer.php`). Lowercase alnum only, so it
 * is shell-inert AND a valid nginx-served directory name; length-bounded to keep
 * it unguessable without being unwieldy. The real access control is the tenant's
 * scoped DB login, not the token — this just keeps the path off casual discovery.
 */
const DBTOOL_TOKEN_RE = /^[a-z0-9]{16,40}$/;
export function isValidDbToolToken(token: string): boolean {
  return DBTOOL_TOKEN_RE.test(String(token ?? ""));
}

/** Docroot + parent dir for a subdomain, jailed under the account home. */
export function subdomainPaths(username: string, label: string): { dir: string; docroot: string } {
  const dir = `/home/${username}/subdomains/${label}`;
  return { dir, docroot: `${dir}/public_html` };
}

/** Docroot + parent dir for an addon domain, jailed under the account home. */
export function addonDomainPaths(username: string, domain: string): { dir: string; docroot: string } {
  const dir = `/home/${username}/domains/${domain}`;
  return { dir, docroot: `${dir}/public_html` };
}

/**
 * True for a well-formed 5-field cron schedule ("m h dom mon dow"). Each field is
 * restricted to the digits/ranges/steps/lists/`*` cron uses — nothing that could
 * be a shell metacharacter — so the schedule is safe to write into a crontab.
 * (Named shortcuts like @daily are intentionally NOT accepted here.)
 */
const CRON_FIELD_RE = /^[0-9*/,\-]+$/;
export function isValidCronSchedule(schedule: string): boolean {
  const parts = String(schedule ?? "").trim().split(/\s+/);
  if (parts.length !== 5) return false;
  return parts.every((p) => p.length > 0 && p.length <= 40 && CRON_FIELD_RE.test(p));
}

/**
 * True for a cron command safe to place in a crontab line. It runs AS the jailed
 * user (crontab -u <user>), so it is already confined; the only invariants we
 * enforce here protect our own crontab writer: no newlines (one line per job) and
 * no `%` (cron's literal-newline metacharacter), and a sane length.
 */
export function isValidCronCommand(command: string): boolean {
  const c = String(command ?? "");
  if (c.length < 1 || c.length > 500) return false;
  return !/[\n\r%]/.test(c);
}

/* ------------------------------------------------------------------------- *
---WC---
396 lib/hosting.ts

/* ------------------------------------------------------------------------- *
 * Provisioner hardening (config generators for NEW accounts)
 *
 * These are the security-critical config the provisioner writes onto a
 * MULTI-TENANT box. They are pure + unit-tested here because a subtle gap in
 * any of them (a missing dangerous PHP function, a world-readable webroot, an
 * un-escaped GRANT wildcard) is not one customer's bug — it is a cross-tenant
 * breach. worker/hosting.ts imports these; it never re-derives them inline.
 * ------------------------------------------------------------------------- */

/**
 * PHP functions blocked in every account's FPM pool (`disable_functions`).
 *
 * On a shared box `disable_functions` is a real isolation control, not defence
 * in depth: without it a tenant's PHP can shell out (`exec`/`system`), fork out
 * of `open_basedir` (`pcntl_exec` — compiled into PHP, so it bypasses a naive
 * blocklist), rewrite its own env (`putenv` → `LD_PRELOAD`/`GCONV_PATH`
 * tricks), plant symlinks that escape the jail (`symlink`/`link`), or reach the
 * host via `ffi`/`dl`. Everything a tenant could use to break out of its pool
 * belongs here. Kept sorted-by-purpose + deduped.
 */
export const PHP_DISABLED_FUNCTIONS: readonly string[] = [
  // Command execution — the classic RCE surface.
  "exec", "passthru", "shell_exec", "system", "proc_open", "popen",
  // Process control — pcntl_exec is compiled in and bypasses the above blocklist;
  // fork/signal/proc_nice let a tenant escape open_basedir or starve neighbours.
  "pcntl_exec", "pcntl_fork", "pcntl_signal", "proc_nice",
  // Environment + dynamic loading — putenv enables LD_PRELOAD-style escapes,
  // dl/ffi load native code straight past the PHP sandbox.
  "putenv", "dl", "ffi",
  // Filesystem jail-breaks — symlink/link can point out of open_basedir.
  "symlink", "link",
  // Mail — a shared box is a prized spam relay. mail() is blocked; mb_send_mail
  // is an equivalent wrapper, and imap_open/imap_mail can send too — block all.
  "mail", "mb_send_mail", "imap_open", "imap_mail",
  // Misc host-reach / info-leak vectors.
  "error_log", "curl_multi_exec", "parse_ini_file", "show_source",
] as const;

/** The comma-separated `disable_functions` value for a pool config. */
export function phpDisableFunctions(): string {
  return [...PHP_DISABLED_FUNCTIONS].join(",");
}

/**
 * Filesystem ownership + permission plan for a new account.
 *
 * The isolation goal: nginx (www-data) must serve a tenant's files, but a
 * NEIGHBOURING tenant (its own jailed unix user) must not be able to read them
 * — so nothing here is world-readable (the old `755` webroot let any tenant
 * read a peer's wp-config.php if open_basedir was ever escaped).
 *
 *  - home    `711 root:root` — chroot-safe (root-owned, no group/other write)
 *            and world-traversable so nginx can *reach* the webroot, but NOT
 *            world-listable, so a peer can't enumerate the home.
 *  - webroot `2750 <user>:www-data` — owner (the tenant's FPM pool) read/write,
 *            group www-data (nginx) read, world nothing. The setgid bit makes
 *            files the tenant creates inherit the www-data group so nginx keeps
 *            serving them; peers (neither owner nor in www-data) are shut out.
 *  - tmp     `700 <user>:<user>` — private PHP scratch (upload/session dir).
 *
 * nginx reaches tenant files via GROUP membership (www-data owns the webroot
 * group), never via world bits — that is the whole point of dropping 755.
 */
export function accountFsPlan(username: string): {
  home: { owner: string; mode: string };
  webroot: { owner: string; mode: string };
  tmp: { owner: string; mode: string };
  nginxGroup: string;
} {
  return {
    home: { owner: "root:root", mode: "711" },
    webroot: { owner: `${username}:www-data`, mode: "2750" },
    tmp: { owner: `${username}:${username}`, mode: "700" },
    nginxGroup: "www-data",
  };
}

/** PHP-FPM pool hardening limits applied to every account pool. */
export const FPM_MEMORY_LIMIT = "256M";
export const FPM_REQUEST_TERMINATE_TIMEOUT = "120s";

/**
 * The per-account PHP-FPM pool config (the PHP isolation boundary). Pure: given
 * the validated username + jailed paths, returns the exact pool file contents.
 *
 * open_basedir is scoped to the account home (+ the shared PHP lib) and NO
 * LONGER includes `/tmp`: PHP's tmp/session dirs are redirected into the home,
 * so a world-writable `/tmp` on open_basedir was just an unnecessary shared
 * surface between tenants. memory_limit + request_terminate_timeout cap a
 * single tenant from exhausting the shared box.
 */
export function fpmPoolConfig(username: string, home: string, webroot: string): string {
  const sock = `/run/php/${username}.sock`;
  return [
    `[${username}]`,
    `user = ${username}`,
    `group = ${username}`,
    `listen = ${sock}`,
    `listen.owner = ${username}`,
    `listen.group = www-data`,
    `pm = ondemand`,
    `pm.max_children = 6`,
    `pm.process_idle_timeout = 30s`,
    `chdir = ${webroot}`,
    // TRAILING SLASHES are load-bearing: `${home}` (no slash) would also authorise
    // `${home}2/…` — a sibling tenant's home — so open_basedir must pin the prefix
    // to the directory itself via the trailing `/` (same for the shared PHP lib).
    `php_admin_value[open_basedir] = ${home}/:/usr/share/php/`,
    `php_admin_value[disable_functions] = ${phpDisableFunctions()}`,
    `php_admin_value[memory_limit] = ${FPM_MEMORY_LIMIT}`,
    `php_admin_value[request_terminate_timeout] = ${FPM_REQUEST_TERMINATE_TIMEOUT}`,
    `php_admin_value[upload_tmp_dir] = ${home}/tmp`,
    `php_admin_value[session.save_path] = ${home}/tmp`,
  ].join("\n");
}

/**
 * Escape a MySQL identifier for the `ON <db>.*` clause of a GRANT.
 *
 * In GRANT, `_` and `%` are LIKE-wildcards: an un-escaped grant on `nxuser_wp`
 * silently also grants on `nxuserXwp`, `nxuser_wpZ`, … i.e. a neighbouring
 * tenant's database. Escaping them (and the escape char itself) with a
 * backslash pins the grant to exactly one database.
 */
export function escapeGrantDbName(name: string): string {
  return name.replace(/([\\_%])/g, "\\$1");
}

/**
 * The scoped SQL that creates one account database + user and grants that user
 * privileges on THAT DATABASE ONLY.
 *
 * Security invariants (audited): the GRANT is pinned to the exact db via
 * escapeGrantDbName (no wildcard bleed into a peer's db), it is NEVER `*.*`,
 * and `ALL PRIVILEGES` at database scope confers no global FILE/SUPER (those
 * are server-level and cannot be granted by a db-scoped GRANT). Returns plain
 * SQL with real backticks; the caller shell-escapes for `mysql -e`.
 */
export function buildScopedGrantSql(dbName: string, dbUser: string, dbPass: string): string {
  const grantName = escapeGrantDbName(dbName);
  return (
    `CREATE DATABASE IF NOT EXISTS \`${dbName}\`; ` +
    `CREATE USER IF NOT EXISTS '${dbUser}'@'localhost' IDENTIFIED BY '${dbPass}'; ` +
    `GRANT ALL PRIVILEGES ON \`${grantName}\`.* TO '${dbUser}'@'localhost'; ` +
    `FLUSH PRIVILEGES;`
  );
}

// ---- Proprietary in-portal DB manager (Nxeon-built, replaces Adminer) -------

/** The account-level MySQL user the in-portal DB manager authenticates as. One
 *  per account, derived from the (already shell/SQL-safe) username. Kept <=32
 *  chars — MySQL's user-name limit. Usernames are `[a-z][a-z0-9]{2,31}` (no
 *  underscore), so `<username>_mgr` is unambiguous and never collides with a
 *  per-database user (`<username>_<slug>`) whose slug can't be the reserved
 *  literal `mgr` used here… — we simply reserve this name for the manager. */
export function dbMgrUserFor(username: string): string {
  return `${username}_mgr`.slice(0, 32);
}

/** Is this a syntactically valid MySQL account/database identifier for OUR
 *  generated names? Deliberately strict — only the charset our provisioner ever
 *  produces (`<username>_<slug>` / `<username>_mgr`), so a value that reaches the
 *  `mysql` command line as a flag can carry no shell metacharacters. NOT for
 *  arbitrary user-supplied table names (those are validated by membership against
 *  SHOW TABLES + backtick-quoting, never interpolated into a shell). */
const DB_IDENT_RE = /^[a-z0-9_]{1,64}$/;
export function isValidDbIdentifier(name: string): boolean {
  return DB_IDENT_RE.test(String(name ?? ""));
}

/**
 * The grant that scopes the DB-manager user to EXACTLY this account's own
 * databases and nothing else. The privilege target is `<username>\_%`.* — the
 * account username, a LITERAL underscore (escaped so it is not a LIKE wildcard),
 * then `%`. That matches every `<username>_<...>` database the account can create
 * and, because usernames are `[a-z][a-z0-9]{2,31}` (never contain `_`), can never
 * match another tenant's `<otheruser>_<...>` databases — the same escaped-glob
 * boundary the backup/terminate paths already rely on.
 *
 * Security invariants (mirror buildScopedGrantSql): the grant is db-scoped, never
 * `*.*`, so `ALL PRIVILEGES` here confers NO server-level FILE/PROCESS/SUPER — the
 * manager user therefore cannot read files (LOAD_FILE/INTO OUTFILE), see other
 * connections, or touch the `mysql`/system schemas. Returns plain SQL with real
 * backticks; the caller shell-escapes for `mysql -e`.
 */
export function buildDbMgrGrantSql(username: string, mgrUser: string, mgrPass: string): string {
  // `${username}\_%` — escape only the underscore (username itself is [a-z0-9]).
  const scope = `${username}\\_%`;
  return (
    `CREATE USER IF NOT EXISTS '${mgrUser}'@'localhost' IDENTIFIED BY '${mgrPass}'; ` +
    `ALTER USER '${mgrUser}'@'localhost' IDENTIFIED BY '${mgrPass}'; ` +
    `GRANT ALL PRIVILEGES ON \`${scope}\`.* TO '${mgrUser}'@'localhost'; ` +
    `FLUSH PRIVILEGES;`
  );
}

