253	/**
254	 * The isolation shell for one account (HTTP-only vhost; SSL added later by the
255	 * sweep once DNS points at us). Every interpolated value has already cleared a
256	 * validator, so nothing here can be a shell metacharacter.
257	 */
258	async function applyIsolation(
259	  conn: Client,
260	  a: { username: string; primaryDomain: string; diskQuotaMB: number; sftpPassword: string },
261	  php: string,
262	): Promise<void> {
263	  const u = a.username;
264	  const d = a.primaryDomain;
265	  if (!isValidUnixUsername(u)) throw new Error(`refusing unsafe username ${u}`);
266	  if (!isValidHostingDomain(d)) throw new Error(`refusing unsafe domain ${d}`);
267	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
268	  const { home, webroot } = accountPaths(u);
269	  const quotaGB = Math.max(1, Math.round(a.diskQuotaMB / 1024));
270	  const hardBlocks = diskQuotaBlocks(quotaGB);
271	  const softBlocks = Math.floor(hardBlocks * 0.95);
272	  const inodes = diskQuotaInodes(quotaGB);
273	  const sock = `/run/php/${u}.sock`;
274	
275	  // 1. Jailed user. Home is ROOT-owned (a chroot requirement); the user owns only
276	  //    public_html + tmp under it. nologin shell — SFTP-only via the chroot below.
277	  //
278	  // Perms come from the tested accountFsPlan(): home 711 (chroot-safe + nginx can
279	  // TRAVERSE to the webroot but a peer tenant can't LIST the home), webroot
280	  // 2750 <user>:www-data (nginx reads via the www-data GROUP, never world — the
281	  // old world-readable 755 let any tenant read a neighbour's wp-config.php if
282	  // open_basedir was escaped; the setgid bit keeps tenant-created files in the
283	  // www-data group so nginx keeps serving them), tmp 700 (private PHP scratch).
284	  const fs = accountFsPlan(u);
285	  await run(conn, "create user", `id -u ${u} >/dev/null 2>&1 || useradd -m -d ${home} -s /usr/sbin/nologin ${u}`);
286	  await run(
287	    conn,
288	    "chroot-safe home",
289	    `mkdir -p ${webroot} ${home}/tmp && ` +
290	      `chown ${fs.home.owner} ${home} && chmod ${fs.home.mode} ${home} && ` +
291	      `chown ${fs.webroot.owner} ${webroot} && chmod ${fs.webroot.mode} ${webroot} && ` +
292	      `chown ${fs.tmp.owner} ${home}/tmp && chmod ${fs.tmp.mode} ${home}/tmp`,
293	  );
294	  await run(conn, "sftp password", `printf '%s:%s' ${u} '${a.sftpPassword}' | chpasswd`);
295	
296	  // 2. Disk quota (fs must have usrquota — node onboarding enables it). The last
297	  //    two fields are the INODE soft/hard limits: `0 0` = unlimited inodes, which
298	  //    let a tenant exhaust the shared filesystem's inode table with millions of
299	  //    tiny files (a DoS the block quota can't stop), so we pass real caps (HIGH-2).
300	  await run(conn, "disk quota", `command -v setquota >/dev/null 2>&1 && setquota -u ${u} ${softBlocks} ${hardBlocks} ${inodes.soft} ${inodes.hard} /home || echo 'quota tool absent — skipped'`);
301	
302	  // 3. Per-user PHP-FPM pool — THE PHP isolation boundary.
303	  await writeFpmPool(conn, u, home, webroot, php);
304	
305	  // 4. Self-signed FALLBACK cert, so nginx can listen on 443 from the very first
306	  //    second the account exists. Without this the account served HTTP-only until
307	  //    the SSL sweep ran, and any visitor hitting https:// got ERR_CONNECTION_REFUSED
308	  //    while the panel already said "active" (the kaymo failure). Idempotent: only
309	  //    generated if absent. Key is 600 root; the whole dir is root-owned + off the
310	  //    tenant tree, so a tenant can never read or swap its own TLS key.
311	  const ssCertDir = selfSignedCertDir(u);
312	  await run(
313	    conn,
314	    "self-signed fallback cert",
315	    `mkdir -p ${ssCertDir} && chmod 700 ${ssCertDir} && ` +
316	      `if [ ! -s ${ssCertDir}/fullchain.pem ] || [ ! -s ${ssCertDir}/privkey.pem ]; then ` +
317	      `openssl req -x509 -newkey rsa:2048 -nodes -keyout ${ssCertDir}/privkey.pem -out ${ssCertDir}/fullchain.pem ` +
318	      `-days 3650 -subj "/CN=${d}" -addext "subjectAltName=DNS:${d},DNS:www.${d}"; fi && ` +
319	      `chown -R root:root ${ssCertDir} && chmod 600 ${ssCertDir}/privkey.pem && chmod 644 ${ssCertDir}/fullchain.pem`,
320	  );
321	
322	  // 5. Name-based vhost — ALWAYS listens on 443, using the self-signed fallback
323	  //    until the SSL sweep swaps in the real Let's Encrypt cert.
324	  await installVhost(conn, u, renderHostingVhost(u, d, webroot, sock, { certDir: ssCertDir, real: false }));
325	
326	  // 6. Chrooted SFTP — sshd -t GUARDED so a bad config can never lock out the box.
327	  const sftpConf = [
328	    `Match User ${u}`,
329	    `    ChrootDirectory ${home}`,
330	    `    ForceCommand internal-sftp`,
331	    `    AllowTcpForwarding no`,
332	    `    X11Forwarding no`,
333	  ].join("\n");
334	  const sshdFile = `/etc/ssh/sshd_config.d/nxeon-${u}.conf`;
335	  await run(
336	    conn,
337	    "sftp chroot (guarded)",
338	    // Write to a temp include, validate the WHOLE sshd config, and only then move
339	    // it into place + reload. If sshd -t fails, discard — never reload a broken config.
340	    `mkdir -p /etc/ssh/sshd_config.d && cat > ${sshdFile}.new <<'SSHD'\n${sftpConf}\nSSHD\n` +
341	      `cp -f ${sshdFile}.new ${sshdFile} && if sshd -t 2>/dev/null; then systemctl reload ssh 2>/dev/null || systemctl reload sshd; else rm -f ${sshdFile}; echo 'sshd -t rejected the chroot block — SFTP not enabled, box untouched'; fi; rm -f ${sshdFile}.new`,
342	  );
343	}
