685	// ---- Serve-verification + self-heal health sweep ---------------------------
686	
687	/** Parse the numeric HTTP status curl printed with `-w '%{http_code}'`. Returns 0
688	 *  when curl couldn't get a response (connection refused/timeout → "000"). */
689	function parseHttpCode(out: string): number {
690	  const n = parseInt(out.trim().slice(-3), 10);
691	  return Number.isFinite(n) ? n : 0;
692	}
693	/** A 2xx/3xx means nginx actually answered with a page/redirect for this vhost —
694	 *  the anti-ERR_CONNECTION_REFUSED signal. 4xx/5xx/000 are NOT counted as serving
695	 *  (we never mark an account falsely healthy). */
696	function servesOk(code: number): boolean {
697	  return code >= 200 && code < 400;
698	}
699	
700	/**
701	 * Serve-verification + self-heal for ACTIVE accounts. From the node itself it
702	 * curls http/https for each account's own Host header and records whether nginx
703	 * genuinely answers on 80/443 (serveHttpOk / serveHttpsOk) — so the panel reflects
704	 * REALITY, never "active" while HTTPS refuses (the kaymo failure). It also
705	 * SELF-HEALS: if a real Let's Encrypt cert exists but 443 isn't serving, it
706	 * reinstalls the real-cert vhost and reloads nginx; if HTTPS just isn't issued yet
707	 * it's left to hostingSslSweep. Gated ENABLED && !SANDBOX like every other node
708	 * path. `onlyRequested` processes just the accounts a customer clicked "Check now"
709	 * on (recheckRequested), so the button feels immediate; the full sweep runs on the
710	 * ~10-min tick. Returns the number of accounts processed.
711	 */
712	export async function hostingHealthSweep(opts: { onlyRequested?: boolean } = {}): Promise<number> {
713	  const onlyRequested = opts.onlyRequested === true;
714	  if (SANDBOX) {
715	    // Simulate a healthy check so the dev panel + the "Check now" button resolve,
716	    // and the recheck flag clears. HTTPS "verified" mirrors the (simulated) sslActive.
717	    const accts = await db.hostingAccount.findMany({
718	      where: onlyRequested ? { status: "ACTIVE", recheckRequested: true } : { status: "ACTIVE" },
719	      select: { id: true, sslActive: true },
720	      take: onlyRequested ? 25 : 50,
721	    });
722	    for (const a of accts) {
723	      await db.hostingAccount.update({
724	        where: { id: a.id },
725	        data: {
726	          serveHttpOk: true,
727	          serveHttpsOk: true,
728	          healthNote: a.sslActive ? "HTTPS live — verified" : "HTTP live, HTTPS issuing",
729	          healthCheckedAt: new Date(),
730	          recheckRequested: false,
731	        },
732	      }).catch(() => undefined);
733	    }
734	    return accts.length;
735	  }
736	  if (!ENABLED) return 0;
737	
738	  const accts = await db.hostingAccount.findMany({
739	    where: onlyRequested ? { status: "ACTIVE", recheckRequested: true } : { status: "ACTIVE" },
740	    include: { node: true },
741	    // Newest-requested first so a customer who just clicked "Check now" is served
742	    // before the routine backlog even in the full sweep.
743	    orderBy: [{ recheckRequested: "desc" }, { updatedAt: "asc" }],
744	    take: onlyRequested ? 25 : 30,
745	  });
746	  let processed = 0;
747	  for (const a of accts) {
748	    try {
749	      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
750	      const d = a.primaryDomain;
751	      const u = a.username;
752	      let serveHttpOk = false;
753	      let serveHttpsOk = false;
754	      let sslActive = a.sslActive;
755	      let note = "";
756	      const conn = await connectNode(a.node);
757	      try {
758	        const httpR = await exec(conn, `curl -s -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' http://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
759	        const httpsR = await exec(conn, `curl -sk -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' https://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
760	        serveHttpOk = servesOk(parseHttpCode(httpR.out));
761	        serveHttpsOk = servesOk(parseHttpCode(httpsR.out));
762	
763	        // Does a REAL Let's Encrypt cert exist on the node for this domain?
764	        const liveDir = `/etc/letsencrypt/live/${d}`;
765	        const haveReal = (await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`)).out.trim() === "yes";
766	
767	        // SELF-HEAL: a real cert exists but 443 isn't serving → the vhost is stale
768	        // or nginx dropped the block. Reinstall the real-cert vhost + reload, then
769	        // re-verify. This is the recovery from exactly the state kaymo hit.
770	        if (haveReal && !serveHttpsOk) {
771	          const { webroot } = accountPaths(u);
772	          try {
773	            await installVhost(conn, u, renderHostingVhost(u, d, webroot, `/run/php/${u}.sock`, { certDir: liveDir, real: true }));
774	            const reR = await exec(conn, `curl -sk -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' https://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
775	            serveHttpsOk = servesOk(parseHttpCode(reR.out));
776	            if (serveHttpsOk) note = "Recovered HTTPS (reinstalled certificate vhost)";
777	          } catch (e) {
778	            note = "HTTPS repair failed — support notified";
779	            console.error(`[hosting] health self-heal ${a.id} failed`, e);
780	          }
781	        }
782	        if (haveReal && serveHttpsOk) sslActive = true; // real cert is live
783	
784	        if (!note) {
785	          if (sslActive && serveHttpsOk) note = "HTTPS live — verified";
786	          else if (serveHttpsOk || serveHttpOk) note = "HTTP live, HTTPS issuing";
787	          else {
788	            // Nothing served locally. If DNS isn't pointed at us yet, say so;
789	            // otherwise it's a serving fault the SSL sweep / support will chase.
790	            const pointed = await domainPointsAt(d, a.node.publicIp);
791	            note = pointed ? "Serving issue — being checked" : "DNS not detected yet";
792	          }
793	        }
794	      } finally {
795	        try { conn.end(); } catch { /* */ }
796	      }
797	      await db.hostingAccount.update({
798	        where: { id: a.id },
799	        data: { serveHttpOk, serveHttpsOk, sslActive, healthNote: note.slice(0, 200), healthCheckedAt: new Date(), recheckRequested: false },
800	      });
801	      processed++;
802	    } catch (e) {
803	      console.error(`[hosting] health sweep ${a.id} failed`, e);
804	      // Clear the recheck flag even on failure so a broken node can't wedge the
805	      // fast path into re-processing the same account every 30s forever.
806	      await db.hostingAccount.update({ where: { id: a.id }, data: { recheckRequested: false } }).catch(() => undefined);
807	    }
808	  }
809	  return processed;
810	}
