821	/** Move an account's FPM pool to a new PHP version (socket path is unchanged, so
822	 *  the vhost never needs editing). */
823	async function taskPhpSwitch(conn: Client, a: { id: string; username: string; phpVersion: string }, payload: string | null): Promise<void> {
824	  const version = String(JSON.parse(payload || "{}").version ?? "");
825	  if (!/^\d\.\d$/.test(version)) throw new Error("invalid php version");
826	  const { home, webroot } = accountPaths(a.username);
827	  if (version !== a.phpVersion) {
828	    await run(conn, "remove old pool", `rm -f /etc/php/${a.phpVersion}/fpm/pool.d/${a.username}.conf; systemctl reload php${a.phpVersion}-fpm 2>/dev/null || true`);
829	  }
830	  await writeFpmPool(conn, a.username, home, webroot, version);
831	  await db.hostingAccount.update({ where: { id: a.id }, data: { phpVersion: version } });
832	}
