834	// ---- Account lifecycle (suspend / unsuspend / terminate) --------------------
835	// All three validate the username first (it flows into shell), and are written to
836	// be idempotent + safe to re-run. They only touch this account's own files.
837	
838	type LifecycleAccount = { id: string; username: string; phpVersion: string };
839	
840	// Validate BOTH shell-bound fields up front. username is a strict allowlist;
841	// phpVersion is stored (schema default "8.3") but re-checked here so it can never
842	// carry anything but `\d.\d` into an `rm`/`systemctl` line (security audit LOW-1).
843	function assertLifecycleSafe(a: LifecycleAccount): void {
844	  if (!isValidUnixUsername(a.username)) throw new Error("unsafe account username");
845	  if (!/^\d\.\d$/.test(a.phpVersion)) throw new Error("unsafe php version");
846	}
847	
848	/** Take an account OFFLINE without destroying data: drop the nginx site, remove
849	 *  the FPM pool (no PHP), and lock the unix user (no SFTP/login). Reversible. */
850	async function taskSuspend(conn: Client, a: LifecycleAccount): Promise<void> {
851	  assertLifecycleSafe(a);
852	  await run(conn, "suspend: disable vhost", `rm -f /etc/nginx/sites-enabled/hosting-${a.username}.conf; nginx -t && systemctl reload nginx || true`);
853	  await run(conn, "suspend: remove fpm pool", `rm -f /etc/php/${a.phpVersion}/fpm/pool.d/${a.username}.conf; systemctl reload php${a.phpVersion}-fpm 2>/dev/null || true`);
854	  await run(conn, "suspend: lock user", `usermod -L ${a.username} 2>/dev/null || true; pkill -u ${a.username} 2>/dev/null || true`);
855	}
856	
857	/** Reverse a suspend: re-enable the site, rebuild the FPM pool, unlock the user. */
858	async function taskUnsuspend(conn: Client, a: LifecycleAccount): Promise<void> {
859	  assertLifecycleSafe(a);
860	  const { home, webroot } = accountPaths(a.username);
861	  await writeFpmPool(conn, a.username, home, webroot, a.phpVersion);
862	  await run(conn, "unsuspend: enable vhost", `ln -sfn /etc/nginx/sites-available/hosting-${a.username}.conf /etc/nginx/sites-enabled/hosting-${a.username}.conf; nginx -t && systemctl reload nginx || true`);
863	  await run(conn, "unsuspend: unlock user", `usermod -U ${a.username} 2>/dev/null || true`);
864	}
865	
866	/** Fully deprovision: remove the vhost + FPM pool, delete the jailed user and its
867	 *  home, and drop every database AND db-user scoped to this account (`<user>_*`). */
868	async function taskTerminate(conn: Client, a: LifecycleAccount): Promise<void> {
869	  assertLifecycleSafe(a);
870	  await run(conn, "terminate: remove vhost", `rm -f /etc/nginx/sites-enabled/hosting-${a.username}.conf /etc/nginx/sites-available/hosting-${a.username}.conf; systemctl reload nginx 2>/dev/null || true`);
871	  await run(conn, "terminate: remove fpm pool", `rm -f /etc/php/${a.phpVersion}/fpm/pool.d/${a.username}.conf; systemctl reload php${a.phpVersion}-fpm 2>/dev/null || true`);
872	  // Drop this account's scoped databases (`<user>_*`) AND the matching db-users
873	  // (named `<user>_<slug>` / `<user>_wp`, NOT bare `<user>` — audit MEDIUM-2).
874	  await run(conn, "terminate: drop scoped dbs + users", `for d in $(mysql -N -e "SHOW DATABASES LIKE '${a.username}\\_%'" 2>/dev/null); do mysql -e "DROP DATABASE \\\`$d\\\`" 2>/dev/null; done; for u in $(mysql -N -e "SELECT User FROM mysql.user WHERE User LIKE '${a.username}\\_%'" 2>/dev/null); do mysql -e "DROP USER IF EXISTS '$u'@'localhost'" 2>/dev/null; done; true`);
875	  await run(conn, "terminate: delete user + home", `pkill -u ${a.username} 2>/dev/null; sleep 1; userdel -r ${a.username} 2>/dev/null || true`);
876	}
