963	/** Archive the account's home + DB dumps to a node-local backups dir.
964	 *
965	 * SECURITY (audit 2026-08-01, cross-tenant DB compromise): the DB dumps are
966	 * written to a ROOT-ONLY directory OUTSIDE the tenant's chroot and are NEVER
967	 * chowned to the tenant. The old code dumped into ${home}/.dbdump and chowned it
968	 * to the account user, so the tenant — who holds live SFTP creds chrooted to
969	 * ${home} — could race in and overwrite <db>.sql with arbitrary SQL that restore
970	 * later piped into `mysql` as root (a shared-node-wide GRANT/USE). Keeping the
971	 * dumps root-owned and off the tenant tree means the archived SQL is always our
972	 * own mysqldump output, never tenant-controlled. */
973	async function taskBackup(conn: Client, a: { id: string; username: string }, tsLabel: string): Promise<void> {
974	  const u = a.username;
975	  const dir = `/var/hosting-backups/${u}`;
976	  const dumpDir = `${dir}/dbdump`;
977	  const path = `${dir}/${tsLabel}.tar.gz`;
978	  // Root-only staging for the DB dumps; the whole dir is 700 root:root so the
979	  // tenant can neither read nor tamper with it.
980	  await run(
981	    conn,
982	    "dump dbs",
983	    `rm -rf ${dumpDir}; mkdir -p ${dumpDir}; chown -R root:root ${dir}; chmod 700 ${dir} ${dumpDir}; ` +
984	      `for dbn in $(mysql -N -e "SHOW DATABASES LIKE '${u}\\_%'" 2>/dev/null); do mysqldump "$dbn" > ${dumpDir}/"$dbn".sql 2>/dev/null; done`,
985	  );
986	  // One archive holding the home tree (${u}/…) and the root-owned dumps (dbdump/…).
987	  await run(conn, "tar home", `tar -czf ${path} -C /home ${u} -C ${dir} dbdump && rm -rf ${dumpDir}`);
988	  const st = await exec(conn, `stat -c %s ${path} 2>/dev/null || echo 0`);
989	  const sizeBytes = Math.max(0, Math.min(2_000_000_000, Number(st.out.trim()) || 0));
990	  await db.hostingBackup.create({ data: { accountId: a.id, path, sizeBytes } });
991	  // Retain the newest 5 per account; delete older files + rows.
992	  const all = await db.hostingBackup.findMany({ where: { accountId: a.id }, orderBy: { createdAt: "desc" } });
993	  for (const old of all.slice(5)) {
994	    await exec(conn, `rm -f ${old.path}`).catch(() => undefined);
995	    await db.hostingBackup.delete({ where: { id: old.id } }).catch(() => undefined);
996	  }
997	}
