999	/** Restore a backup over the account (destructive: overwrites files + DBs).
1000	 *
1001	 * The archive is extracted to a ROOT-ONLY staging dir (never straight into the
1002	 * tenant's writable tree), and only DB dumps in THIS tenant's namespace
1003	 * (`${u}_*.sql`) are replayed — so a restore can never touch another tenant's
1004	 * database, and the SQL content is our own dump, not anything the tenant could
1005	 * have planted (see taskBackup). */
1006	async function taskRestore(conn: Client, a: { id: string; username: string }, payload: string | null): Promise<void> {
1007	  const backupId = String(JSON.parse(payload || "{}").backupId ?? "");
1008	  const b = await db.hostingBackup.findFirst({ where: { id: backupId, accountId: a.id } });
1009	  if (!b) throw new Error("backup not found");
1010	  const u = a.username;
1011	  const { home, webroot } = accountPaths(u);
1012	  if (!/^\/var\/hosting-backups\/[a-z0-9]+\/[A-Za-z0-9._-]+\.tar\.gz$/.test(b.path)) throw new Error("unsafe backup path");
1013	  const stage = `/var/hosting-backups/${u}/.restore`;
1014	  await run(conn, "extract", `rm -rf ${stage}; mkdir -p ${stage}; chown root:root ${stage}; chmod 700 ${stage}; tar -xzf ${b.path} -C ${stage}`);
1015	  // Files: the archive root holds ${u}/… — copy it back over the home.
1016	  await run(conn, "restore files", `[ -d ${stage}/${u} ] && cp -a ${stage}/${u}/. ${home}/ 2>/dev/null; true`);
1017	  // DBs: replay ONLY dumps named for this tenant's own databases (${u}_*). The
1018	  // shell `case` guard is belt-and-braces on top of the glob — a dump for
1019	  // another tenant's DB is never fed to mysql.
1020	  await run(
1021	    conn,
1022	    "restore dbs",
1023	    `for f in ${stage}/dbdump/${u}_*.sql; do [ -f "$f" ] || continue; bn=$(basename "$f" .sql); ` +
1024	      `case "$bn" in ${u}_*) mysql "$bn" < "$f" 2>/dev/null;; esac; done`,
1025	  );
1026	  // Re-assert the hardened perms the restored tree may have flattened: webroot
1027	  // stays <user>:www-data setgid (nginx reads via group, peers don't), tmp private.
1028	  const rfs = accountFsPlan(u);
1029	  await run(
1030	    conn,
1031	    "fix perms",
1032	    `chown -R ${rfs.webroot.owner} ${webroot} 2>/dev/null; chmod ${rfs.webroot.mode} ${webroot} 2>/dev/null; ` +
1033	      `chown -R ${rfs.tmp.owner} ${home}/tmp 2>/dev/null; chmod ${rfs.tmp.mode} ${home}/tmp 2>/dev/null; rm -rf ${stage}; true`,
1034	  );
1035	}
