1	/**
2	 * NxCloud — managed Nextcloud provisioning + lifecycle glue.
3	 *
4	 * NxCloud rides the existing VPS provisioner: an instance is backed by a real
5	 * `Server`, so the VM is cloned/resized/booted by `worker/index.ts` `provision`
6	 * exactly like any VPS, and it renews / duns / suspends / terminates through the
7	 * audited billing sweep with NO money code here. The ONLY app-specific work is:
8	 *
9	 *   1. `nxcloudSetupForServer` — a small hook `provision` calls right before it
10	 *      builds the cloud-init snippet. If the VM backs an NxCloud instance it
11	 *      generates the one-time admin password (stored encrypted), flips the
12	 *      instance to PROVISIONING, and returns a bash script that stands Nextcloud
13	 *      up on the VM. Idempotent: the script is safe to re-run and the password is
14	 *      generated once.
15	 *   2. `nxcloudProvisionSweep` — verifies the instance is actually SERVING before
16	 *      calling it ACTIVE (reusing the same "never claim ready for something we
17	 *      couldn't verify" discipline as `provision`), mirrors the backing Server's
18	 *      suspend/terminate state onto the instance, and — after a grace window —
19	 *      surfaces a COMPLETED_WITH_ISSUES-style caveat instead of hanging in
20	 *      PROVISIONING forever.
21	 *   3. `nxcloudTaskSweep` — runs queued admin ops (RESET_ADMIN_PW for MVP).
22	 *
23	 * Nextcloud provides the entire end-user product (web UI, sync clients, sharing,
24	 * versioning); we never build a file-sync engine.
25	 */
26	import { db } from "../lib/db";
27	import { encryptSecret, decryptSecret } from "../lib/crypto-box";
28	import { getSetting } from "../lib/settings";
29	import { SANDBOX } from "../lib/sandbox";
30	import { NXCLOUD_DEFAULT_ZONE, nxcloudFqdn } from "../lib/nxcloud";
31	import { randomBytes } from "node:crypto";
32	
33	const LOG = "[nxcloud]";
34	
35	/** URL-safe admin password, 20 chars, no ambiguous separators. */
36	function generatePassword(): string {
37	  return randomBytes(30).toString("base64url").replace(/[-_]/g, "x").slice(0, 20);
38	}
39	
40	/** The DNS zone every instance lives under: <subdomain>.<zone>. */
41	export async function nxcloudZone(): Promise<string> {
42	  return (await getSetting("nxcloud_zone", NXCLOUD_DEFAULT_ZONE)).trim() || NXCLOUD_DEFAULT_ZONE;
43	}
