45	/**
46	 * The idempotent install script baked into the VM's cloud-init. Installs Docker
47	 * and brings up the official Nextcloud image behind Caddy (which fetches a
48	 * Let's Encrypt cert automatically once `domain` resolves to this VM's public
49	 * IP). The admin user/password are injected so the customer can be shown working
50	 * credentials ONCE — unlike Nextcloud AIO, which self-generates a password we
51	 * could never reveal. Everything is `docker compose up -d`, so a PROVISION retry
52	 * or a re-run simply reconciles the running stack.
53	 */
54	export function nxcloudInstallScript(opts: {
55	  domain: string;
56	  adminUser: string;
57	  adminPass: string;
58	}): string {
59	  const { domain, adminUser, adminPass } = opts;
60	  // DB + Redis passwords are internal to the VM; generated fresh per box and
61	  // never leave it, so a plain random hex is fine.
62	  const dbPass = randomBytes(24).toString("hex");
63	  const dbRoot = randomBytes(24).toString("hex");
64	  return [
65	    "# ---- NxCloud: managed Nextcloud bring-up (idempotent) ----",
66	    "export DEBIAN_FRONTEND=noninteractive",
67	    "command -v docker >/dev/null 2>&1 || (curl -fsSL https://get.docker.com | sh)",
68	    "systemctl enable --now docker || true",
69	    "mkdir -p /opt/nxcloud",
70	    "cat > /opt/nxcloud/.env <<'NXENV'",
71	    `NC_DOMAIN=${domain}`,
