131	/**
132	 * Provisioner hook. Called by `provision` right before it builds cloud-init.
133	 * Returns the install script to append (and stashes it on the server object) when
134	 * the VM backs an NxCloud instance, else null. Generates the one-time admin
135	 * password on first run and flips the instance PENDING → PROVISIONING.
136	 */
137	export async function nxcloudSetupForServer(server: { id: string; hostname: string }): Promise<string | null> {
138	  const inst = await db.nxCloudInstance.findUnique({
139	    where: { serverId: server.id },
140	    include: { plan: true },
141	  });
142	  if (!inst) return null;
143	
144	  // Generate + persist the admin password once (idempotent across PROVISION retries).
145	  let adminPass = decryptSecret(inst.adminPassEnc);
146	  if (!adminPass) {
147	    adminPass = generatePassword();
148	    await db.nxCloudInstance.update({
149	      where: { id: inst.id },
150	      data: { adminPassEnc: encryptSecret(adminPass), status: "PROVISIONING" },
151	    });
152	  } else if (inst.status === "PENDING") {
153	    await db.nxCloudInstance.update({ where: { id: inst.id }, data: { status: "PROVISIONING" } });
154	  }
155	
156	  const zone = await nxcloudZone();
157	  const domain = inst.customDomain?.trim() || nxcloudFqdn(inst.subdomain, zone);
158	  return nxcloudInstallScript({ domain, adminUser: inst.adminUser, adminPass });
159	}
