665	function execRemote(
666	  conn: Client,
667	  cmd: string,
668	  timeoutMs: number
669	): Promise<{ code: number; stdout: string; stderr: string }> {
670	  return new Promise((resolve, reject) => {
671	    conn.exec(cmd, (err, stream: ClientChannel) => {
672	      if (err) return reject(err);
673	      let stdout = "";
674	      let stderr = "";
675	      const timer = setTimeout(() => {
676	        try {
677	          stream.close();
678	        } catch {
679	          /* ignore */
680	        }
681	        reject(new Error("remote command timed out"));
682	      }, timeoutMs);
683	      stream
684	        .on("close", (code: number) => {
685	          clearTimeout(timer);
686	          resolve({ code: code ?? 0, stdout, stderr });
687	        })
688	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
689	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
690	    });
691	  });
692	}
