696	/**
697	 * `execRemote` that never throws — a timed-out or broken command reports exit 1
698	 * with its reason in `stderr`. Every best-effort step uses this so one failed
699	 * probe can never abort the whole migration.
700	 */
701	function sh(conn: Client, cmd: string, timeoutMs: number = SETUP_TIMEOUT_MS): Promise<ExecResult> {
702	  return execRemote(conn, cmd, timeoutMs).catch((e) => ({
703	    code: 1,
704	    stdout: "",
705	    stderr: String(e?.message ?? e),
706	  }));
707	}
