714	// ---- Heartbeats for the long steps ----------------------------------------
715	/**
716	 * A single remote command can legitimately run for MINUTES — `apt-get install`,
717	 * `docker save | ssh | docker load`, `certbot certonly`. During that time the
718	 * engine emits nothing, so the customer's progress bar freezes and the run looks
719	 * hung.
720	 *
721	 * Seen live on 2026-07-25: the run sat silent on 89% "Securing your site…" for a
722	 * full TEN MINUTES while a certbot install blocked on needrestart. The customer
723	 * had no way to tell a wedged migration from a slow one.
724	 *
725	 * So the long steps run inside this wrapper, which emits ONE cheap line every
726	 * `everyMs` naming what is still running and for how long. It is deliberately
727	 * dumb: no extra SSH traffic, no state on the target, and a failing `say` can
728	 * never affect the work it is narrating.
729	 */
730	const HEARTBEAT_MS = 45_000;
731	
732	async function withHeartbeat<T>(
733	  what: string,
734	  say: (line: string) => Promise<void>,
735	  run: () => Promise<T>,
736	  everyMs: number = HEARTBEAT_MS
737	): Promise<T> {
738	  const started = Date.now();
739	  let saying = false;
740	  const timer = setInterval(() => {
741	    // Never let two heartbeats overlap, and never let a reporting failure
742	    // surface as an unhandled rejection — this is narration, not work.
743	    if (saying) return;
744	    saying = true;
745	    const secs = Math.round((Date.now() - started) / 1000);
746	    const elapsed = secs >= 120 ? `${Math.round(secs / 60)} min` : `${secs}s`;
747	    Promise.resolve(say(`  Still working: ${what} (${elapsed} so far) — this step can take a while.`))
748	      .catch(() => {})
749	      .finally(() => {
750	        saying = false;
751	      });
752	  }, Math.max(15_000, everyMs));
753	  // `unref` keeps a stray interval from holding the worker process open.
754	  (timer as unknown as { unref?: () => void }).unref?.();
755	  try {
756	    return await run();
757	  } finally {
758	    clearInterval(timer);
759	  }
760	}
