763	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
764	  return new Promise((resolve, reject) => {
765	    const ws = sftp.createWriteStream(path, { mode: 0o600 });
766	    ws.on("close", () => resolve());
767	    ws.on("error", (e: Error) => reject(e));
768	    ws.end(Buffer.from(content, "utf8"));
769	  });
