75	/** Run the per-family update over SSH and verify the result. */
76	export async function gameUpdate(job: Job): Promise<void> {
77	  const server = await loadGameServer(job.serverId!);
78	  if (SANDBOX) {
79	    // No VM exists, so nothing can be proven. Say that, rather than simulating a
80	    // success message the production path is no longer willing to send.
81	    await notify(
82	      server.userId,
83	      `${server.osTemplate.name} auto-update simulated on ${server.hostname} (sandbox)`,
84	      "Sandbox only — no server was contacted, nothing was updated and nothing was restarted.",
85	      `/dashboard/servers/${server.id}`
86	    );
87	    return;
88	  }
89	  const family = server.osTemplate.family as GameFamily;
90	  if (!GAME_FAMILIES.includes(family)) {
91	    throw new Error(`game update: ${server.hostname} is not a game server`);
92	  }
93	  if (server.status !== "RUNNING") throw new Error("game update: server is not running");
94	  const password = serverRootPassword(server);
95	  if (!server.ipAddress || !password) {
96	    throw new Error("game update: server has no IP/password yet");
97	  }
98	  const scrub = (s: string): string => (password ? s.split(password).join("***") : s);
99	  const href = `/dashboard/servers/${server.id}`;
100	
101	  const remote = updateCommand(family);
102	  let stdout = "";
103	  try {
104	    const r = await execFileP(
105	      "sshpass",
106	      [
107	        "-p",
108	        password,
109	        "ssh",
110	        "-o",
111	        "StrictHostKeyChecking=no",
112	        "-o",
113	        "UserKnownHostsFile=/dev/null",
114	        "-o",
115	        "ConnectTimeout=15",
116	        `root@${server.ipAddress}`,
117	        remote,
118	      ],
119	      { timeout: 600_000, maxBuffer: 4 * 1024 * 1024 }
120	    );
121	    stdout = String(r.stdout ?? "");
122	  } catch (e: any) {
123	    // A non-zero exit is now possible and meaningful, but the markers may still
124	    // have been printed before whatever went wrong — keep them and let the
125	    // verdict decide, rather than discarding evidence.
126	    stdout = String(e?.stdout ?? "");
127	    if (!/^NXGU:END$/m.test(stdout)) {
128	      // execFile embeds the full argv — including `-p <rootPassword>` — into its
129	      // error message/cmd. Rethrow a sanitized error so the password can never be
130	      // stored in Job.error (the worker also redacts as a second line of defense).
131	      const detail = scrub(String(e?.stderr || e?.message || e));
132	      const reason = `game update failed: ${detail}`;
133	      await notifyFailureOnce(
134	        server.userId,
135	        server.id,
136	        `${server.osTemplate.name} auto-update FAILED on ${server.hostname}`,
137	        `We could not reach or run the update on your server, so nothing was updated: ${detail.slice(0, 300)}`,
138	        href
139	      );
140	      throw new Error(reason);
141	    }
142	  }
143	
144	  const facts = parseGameUpdateOutput(scrub(stdout));
145	  const verdict = judgeGameUpdate({ family, hostname: server.hostname, facts });
146	
147	  if (!verdict.ok) {
148	    await notifyFailureOnce(
149	      server.userId,
150	      server.id,
151	      `${server.osTemplate.name} auto-update did not complete on ${server.hostname}`,
152	      verdict.reason,
153	      href
154	    );
155	    // Failing the job is the point: it puts the reason in Job.error and in the
156	    // admin job list instead of leaving a green tick over a dead server.
157	    throw new Error(`game update not verified: ${verdict.reason}`);
158	  }
159	
160	  // Only a real change is an event. This runs every 6 hours, so notifying on
161	  // every pass produced four "<game> updated on <host>" messages a day for a
162	  // server where nothing had been updated — the same erosion `notifyFailureOnce`
163	  // exists to prevent, and with a title that was not true.
164	  if (verdict.notify) await notify(server.userId, verdict.title, verdict.body, href);
165	  else console.log(`[game-update] ${server.hostname}: ${verdict.title} — ${verdict.body}`);
166	}
