168	/**
169	 * Enqueue GAME_UPDATE jobs for every RUNNING game server that has opted into
170	 * auto-update and has no job already in flight. Idempotent / safe to call on a
171	 * timer. Returns nothing; logs a summary.
172	 */
173	export async function gameUpdateSweep(): Promise<void> {
174	  if (SANDBOX) return; // no game servers to update over SSH in the sandbox
175	  const candidates = await db.server.findMany({
176	    where: {
177	      status: "RUNNING",
178	      autoUpdate: true,
179	      osTemplate: { family: { in: [...GAME_FAMILIES] } },
180	    },
181	    select: { id: true, hostname: true, osTemplate: { select: { family: true } } },
182	  });
183	  if (candidates.length === 0) return;
184	
185	  let enqueued = 0;
186	  for (const s of candidates) {
187	    const inflight = await db.job.count({
188	      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
189	    });
190	    if (inflight > 0) continue;
191	    await db.job.create({ data: { type: "GAME_UPDATE", serverId: s.id } });
192	    enqueued++;
193	  }
194	  if (enqueued > 0) {
195	    const checkOnly = candidates.filter((s) => !updatesFromSteam(s.osTemplate.family as GameFamily)).length;
196	    console.log(
197	      `[game-update] sweep enqueued ${enqueued} job(s)` +
198	        (checkOnly > 0
199	          ? ` (${checkOnly} candidate(s) are families with no update source — those runs verify the unit is ` +
200	            `up and change nothing)`
201	          : "")
202	    );
203	  }
204	}
